// "Uglevodorodlar" toifasi tajribalari generatori.
// Ishga tushirish: node tools/seed/reactions/uglevodorodlar.mjs
// Natija: frontend/lab/data/reactions/uglevodorodlar.json (uglevod-0001 namunasi o'zgarishsiz saqlanadi).
// Shu fayl spirtlar-fenollar.mjs va aldegid-ketonlar.mjs uchun umumiy yordamchilarni ham eksport qiladi.
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
export const DATA = join(ROOT, 'frontend', 'lab', 'data');
const SUBS = JSON.parse(readFileSync(join(DATA, 'substances.json'), 'utf8'));

/** Cho'kma kuzatuvi: rang bazadan olinadi */
export function ppt(id, texture) {
  const s = SUBS[id];
  if (!s) throw new Error(`modda yo'q: ${id}`);
  return { species: id, color: s.precipitate?.color || s.appearance?.color, texture: texture || s.precipitate?.texture || 'mayda-kristall' };
}
export function gas(id, desc = null) { return { species: id, desc_uz: desc }; }

/** Qisqa yozuvdan to'liq tajriba yozuvini yasash */
export function mk(category, o) {
  const cond = { heating: false, temp_min_C: null, catalyst: null, medium: null, light: false, note_uz: null, ...(o.cond || {}) };
  if (cond.temp_min_C && o.cond?.heating === undefined) cond.heating = true;
  const r = {
    id: o.id,
    category,
    title_uz: o.title,
    level: o.level,
    topic_uz: o.topic,
    engine: o.engine || 'record',
  };
  if (o.no_reaction) { r.no_reaction = true; r.match = o.match; }
  if (o.equation_free) { r.equation_free = true; r.equation_free_uz = o.equation_free; }
  if (o.extra) Object.assign(r, o.extra);
  Object.assign(r, {
    reactants: o.reactants,
    conditions: cond,
    equation: { molecular: o.eq?.[0] ?? null, ionic_full: o.eq?.[1] ?? null, ionic_net: o.eq?.[2] ?? null, electron_balance: o.eq?.[3] ?? null },
    mechanism: { type: o.mtype || 'organik', steps_uz: o.steps, organic: o.tpl ? { template: o.tpl, params: o.params } : null },
    observations: {
      precipitate: o.ppt ?? null,
      gas: o.gas ?? null,
      solution_color_change: o.color ? { from: o.color[0], to: o.color[1] } : null,
      ...(o.solid ? { solid_color_change: { from: o.solid[0], to: o.solid[1] } } : {}),
      heat: o.heat || 'sezilarsiz',
      flame: o.flame ?? null,
      effects: (o.effects || []).map((type) => ({ type })),
      text_uz: o.text,
    },
    kinetics: o.kin || 'tez',
    apparatus: o.app,
    procedure_uz: o.proc,
    safety_uz: o.safety,
    explanation_uz: o.expl,
    questions_uz: o.q,
    confidence: o.conf || 'yuqori',
  });
  return r;
}

export function writeCategory(category, records, keep = []) {
  const out = { category, reactions: [...keep, ...records] };
  const path = join(DATA, 'reactions', `${category}.json`);
  writeFileSync(path, JSON.stringify(out, null, 1) + '\n');
  console.log(`${category}: ${out.reactions.length} ta yozuv -> ${path}`);
}

