// Ishga tushirilganda faylni yozish (boshqa skriptlar faqat yordamchilarni import qiladi)
if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const path = join(DATA, 'reactions', `${CAT}.json`);
  const keep = existsSync(path) ? JSON.parse(readFileSync(path, 'utf8')).reactions.filter((r) => r.id === 'uglevod-0001') : [];
  records.forEach((r, i) => { r.id = `uglevod-${String(i + 2).padStart(4, '0')}`; });
  writeCategory(CAT, records, keep);
}
